package com.luci.pianoroom;
public class YamahaAudioSettingsTest{
 static void check(boolean v){if(!v)throw new AssertionError();}
 public static void main(String[]args)throws Exception{ChannelSettings c=PianoSoundPresets.apply(new ChannelSettings(),5);c.low=-2;c.hammer=7;c.pan=12;String text=YamahaAudioSettings.encode(c);ChannelSettings d=YamahaAudioSettings.decode(text);check(d.hybrid&&d.texture==c.texture&&d.bodyEnabled&&d.pan==12&&d.hammer==7&&d.low==-2);check(!YamahaAudioSettings.routeProblem(false,true,true,true,true).isEmpty());check(!YamahaAudioSettings.routeProblem(true,true,true,true,false).isEmpty());check(YamahaAudioSettings.routeProblem(true,true,true,true,true).isEmpty());check(!YamahaAudioSettings.routeProblem(true,true,true,false,true).isEmpty());check(YamahaAudioSettings.routeProblem(true,false,false,false,false).isEmpty());check(!YamahaAudioSettings.routeProblem(true,false,false,true,true).isEmpty());try{YamahaAudioSettings.decode(text+"AA");throw new AssertionError();}catch(java.io.IOException expected){}check(SfzBank.accumulate(2L*1073741824,1073741824,SfzBank.MAX_SOURCE_BYTES)==3L*1073741824);try{SfzBank.accumulate(SfzBank.MAX_SOURCE_BYTES,1,SfzBank.MAX_SOURCE_BYTES);throw new AssertionError();}catch(java.io.IOException expected){}System.out.println("PASS: Yamaha USB settings roundtrip; USB-only input, distinct full-output and explicit loopback guards; wide import arithmetic and overflow rejection.");}
}
